mapper.select:
select id, note, type_id as typeId, create_time as createTime
from note


    and status=#{status}
    and user_id=#{userId}
    and type_id=#{typeId}

order by create_time desc, id desc
limit #{pageSize}

select id, note, type_id as typeId, create_time as createTime
from note
where id=#{id}
and status=#{status}

mapper.update:
update note

    note=#{note},
    type_id=#{typeId},
    status=#{status},
    update_time=#{updateTime}

where id=#{id}

mapper.select:
select id, group_name as groupName, create_time as createTime
from note_group


    and status=#{status}
    and user_id=#{userId}

order by create_time desc, id desc
limit #{pageSize}
